{"content": "/** Deterministic PRNG (mulberry32). Seeded course generation. */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function rangeN(rng: () => number, a: number, b: number): number {
  return a + rng() * (b - a);
}

export function pick<T>(rng: () => number, arr: T[]): T {
  return arr[Math.floor(rng() * arr.length) % arr.length];
}

export function intN(rng: () => number, a: number, b: number): number {
  return Math.floor(rangeN(rng, a, b + 1));
}", "path": "/workspace/src/game/rng.ts"}

